 <h2>Database Schema (Prisma)</h2>

<pre>
<span class="kw">model</span> <span class="str">People</span> {
 id <span class="str">String</span> @id @default(cuid())
 type <span class="str">String</span> <span class="cmt">// staff | partner | freelancer | company | investor</span>
 name <span class="str">String</span>
 email <span class="str">String</span>?
 phone <span class="str">String</span>?
 company <span class="str">String</span>?
 stage <span class="str">String</span> <span class="cmt">// Contact | Opportunity | Client | Recurring Client</span>
 tags <span class="str">String</span>[]
 createdAt <span class="str">DateTime</span> @default(now())
 updatedAt <span class="str">DateTime</span> @updatedAt

 projects <span class="str">Project</span>[]
 contacts <span class="str">Contact</span>[]
 activities <span class="str">Activity</span>[]
}

<span class="kw">model</span> <span class="str">Project</span> {
 id <span class="str">String</span> @id @default(cuid())
