<script>
document.querySelectorAll('.slide').forEach((s,i) => {
 const dot = document.createElement('div');
 dot.className = 'nav-dot';
 dot.title = s.querySelector('h2')?.textContent || 'Hero';
 dot.onclick = () => s.scrollIntoView({behavior:'smooth'});
 document.getElementById('navDots').appendChild(dot);
});

const observer = new IntersectionObserver((entries) => {
 entries.forEach(e => {
 if (e.isIntersecting) {
 document.querySelectorAll('.nav-dot').forEach((d,i) => {
 d.classList.toggle('active', i === Array.from(document.querySelectorAll('.slide')).indexOf(e.target));
 });
 }
 });
}, {threshold:0.5});
document.querySelectorAll('.slide').forEach(s => observer.observe(s));
</script>

