 project <span class="str">Project</span> @relation(fields: [projectId], references: [id])
 channel <span class="str">String</span> <span class="cmt">// webchat | whatsapp | email | social | gmail</span>
 direction <span class="str">String</span> <span class="cmt">// inbound | outbound</span>
 content <span class="str">String</span>
 metadata <span class="str">Json</span>?
 sentiment <span class="str">Float</span>? <span class="cmt">// -1 to 1</span>
 createdAt <span class="str">DateTime</span> @default(now())
}

<span class="kw">model</span> <span class="str">AnalyticsRecord</span> {
 id <span class="str">String</span> @id @default(cuid())
 projectId <span class="str">String</span>
 project <span class="str">Project</span> @relation(fields: [projectId], references: [id])
 sentimentScore <span class="str">Float</span>?
 alignmentScore <span class="str">Float</span>?
 healthScore <span class="str">Float</span>?
 generatedAt <span class="str">DateTime</span> @default(now())
}
