 peopleId <span class="str">String</span>
 people <span class="str">People</span> @relation(fields: [peopleId], references: [id])

 conversations <span class="str">Conversation</span>[]
 files <span class="str">ProjectFile</span>[]
 requirements <span class="str">Requirement</span>[]
 milestones <span class="str">Milestone</span>[]
 collaborators <span class="str">Collaborator</span>[]
